INSERT INTO `sitepagecontent` (`id`, `data`, `updatedAt`) VALUES
('ausbildung', '{\"heroQuote\":\"Die Flugschule Hirondelle bietet euch eine qualifizierte, sichere und vielseitige Ausbildung.\",\"introQuote\":\"Wir begleiten euch von den ersten Hüpfern bis zu euren ersten Strecken- und Thermikflügen hier im Odenwald, in der Pfalz, im Kraichtal, im Nahetal und überall sonst auf der Welt.\",\"introHtml\":\"Im Nachfolgenden sind die Ausbildungswege in der Flugschule Hirondelle vom <a href=\\\"/ausbildung/schnupperkurs\\\">Schnupper-/Einsteigerkurs</a> über den <a href=\\\"/ausbildung/l-schein\\\">L-Schein</a> und die <a href=\\\"/ausbildung/a-schein\\\">Höhenflugschulung (A-Schein)</a> bis zum <a href=\\\"/ausbildung/b-schein\\\">unbeschränkten Luftfahrerschein (B-Schein)</a> aufgelistet, hier gelangt ihr zur <a href=\\\"/ausbildung/ausbildungskonzept\\\">Gesamtübersicht</a>.\",\"priceRows\":[{\"name\":\"Schnupper-/Einsteigerkurs\",\"duration\":\"1 – 2 Tage\",\"content\":\"Ausrüstung kennen lernen, die ersten Flüge\",\"price\":\"ab 149,- €\"},{\"name\":\"L-Schein\",\"duration\":\"3 – 4 Tage\",\"content\":\"15 Flüge am Grundkurs-Übungshang\",\"price\":\"620,- €\"},{\"name\":\"Windenschein\",\"duration\":\"3 Tage\",\"content\":\"20 Flüge an der Winde\",\"price\":\"450,- €\"},{\"name\":\"A-Schein\",\"duration\":\"mind. 1 Woche\",\"content\":\"40 Höhenflüge\",\"price\":\"ab 990,- €\"},{\"name\":\"B-Schein\",\"duration\":\"mind. 1 Woche\",\"content\":\"20 Höhenflüge\",\"price\":\"ab 990,- €\"},{\"name\":\"Tandemschein\",\"duration\":\"mind. 1 Woche\",\"content\":\"40 Höhenflüge mit einem Passagier\",\"price\":\"ab 790,- €\"}],\"graphicImage\":\"/images/inhalte/ausbildungswege.png\",\"graphicCaption\":\"hm = ca. Höhenmeter-Differenz zwischen Start- und Landeplatz\",\"graphicButtonLink\":\"\",\"categories\":[{\"heading\":\"Schnupper-/Einsteigerkurs\",\"subheading\":\"Der Anfang einer neuen Leidenschaft....\",\"description\":\"Am Schnuppertag / Einsteigerkurs lernst du die Grundzüge des Gleitschirmfliegens kennen. Anfängliche Aufzieh- und Laufübungen bereiten dich auf deine ersten Flüge vor: Kappe auslegen, Leinen sortieren, Eintrittsöffnungen kontrollieren, damit der Gleitschirm anschließend richtig über euch steigt. Gurtzeug anlegen, Startcheck und los geht\'s zum ersten Versuch.\",\"image\":\"/images/ausbildung-1.jpg\",\"link\":\"/ausbildung/schnupperkurs\"},{\"heading\":\"L-Schein\",\"subheading\":\"Du legst den Grundstein...\",\"description\":\"Aufbauend auf den Schnupperkurs werden im Grundkurs die fehlenden Flüge zur Erlangung des L-Scheins absolviert. Ziel des Kurses ist es, mindestens 15 Flüge am Hang oder an der Winde zu absolvieren, bei denen die Höhendifferenz schon bis zu 200 Meter betragen kann. Kurvenflug und Schirmkontrolle sind einige der Lerninhalte, die in diesem Kurs auf dem Lehrplan stehen.\",\"image\":\"/images/ausbildung-2.jpg\",\"link\":\"/ausbildung/l-schein\"},{\"heading\":\"A-Schein\",\"subheading\":\"Was dich erwartet beim Höhenflugkurs...\",\"description\":\"Aufbauend auf dem Grundkurs, werden beim Höhenflugkurs die ersten 15 Flüge für den beschränkten Luftfahrerschein (A-Schein) durchgeführt. Das Ziel des Höhenflugkurses ist der Höhenflugausweis.\",\"image\":\"/images/ausbildung-3.jpg\",\"link\":\"/ausbildung/a-schein\"},{\"heading\":\"B-Schein\",\"subheading\":\"Auf Strecke mit dem unbeschränkten Luftfahrerschein...\",\"description\":\"Das Gleitpotential des Gleitschirms ausreizen, die Thermik ausfliegen und dann auf Strecke gehen. Von Aufwind zu Aufwind gleiten und die Landschaft aus der Vogelperspektive genießen, das ist der Traum vieler Flieger.\",\"image\":\"/images/ausbildung-4.jpg\",\"link\":\"/ausbildung/b-schein\"},{\"heading\":\"Windenschein\",\"subheading\":\"Windenschlepp mit dem Gleitschirm...\",\"description\":\"Das Schleppen an der Winde ist eine ideale Möglichkeit, auch im Flachland mit dem Gleitschirm in die Luft zu kommen. Der Windenschein ist die ideale Ergänzung zum A-Scheinkurs da ihr hier schnell einen Großteil der nötigen Flüge für die A-Scheinprüfung sammeln könnt.\",\"image\":\"/images/ausbildung-5.jpg\",\"link\":\"/ausbildung/windenschein\"},{\"heading\":\"Tandemschein\",\"subheading\":\"Zusammen mit Freunden zum Fliegen gehen.\",\"description\":\"Zum Fliegen gehen und die Leidenschaft mit Freunden teilen? Mit dem Tandemschein kein Problem! Die Freiheit und die Eindrücke in der Luft mit jemanden teilen zu können ist ein fantastisches Erlebnis sowohl für den Piloten auch für den Passagier. Einfach ein Traum.\",\"image\":\"/images/ausbildung-6.jpg\",\"link\":\"/ausbildung/tandemschein\"}]}', '2026-09-20 17:44:22.212'),
('infos', '{\"companyName\":\"Flugschule Hirondelle\",\"shopLabel\":\"Shop / Theorieraum\",\"shopStreet\":\"Untergasse 27\",\"shopCity\":\"69469 Weinheim\",\"outpostLabel\":\"Außenstelle Landau\",\"outpostStreet\":\"Am Birnbach 6\",\"outpostCity\":\"76829 Landau\",\"phone\":\"+49 (0)6201 8452097\",\"email\":\"info@fs-hirondelle.de\",\"openingHours\":\"nach Vereinbarung\",\"openingHoursNote\":\"(Wird per Newsletter bekannt gegeben)\",\"parkingNote\":\"Die Parkplätze im Hof der Flugschule sind ausschließlich den Anwohnern vorbehalten. Bitte umliegend in den Straßen parken – Danke!\",\"bankAccountHolder\":\"Alexander Schlink\",\"bankName\":\"Sparkasse Südpfalz\",\"iban\":\"DE32 5485 0010 1700 1976 41\",\"bic\":\"SOLADES1SUW\",\"accountNumber\":\"1700197641\",\"bankCode\":\"54850010\",\"routenplanerUrl\":\"https://maps.app.goo.gl/kA2dQXfCx8pgAAJ99\",\"mapsEmbedUrl\":\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5063.258024241909!2d8.672182056413131!3d49.555676284748415!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4797db13e510f3f5%3A0xd6abf4967e8663e9!2sFlugschule%20Hirondelle!5e1!3m2!1sde!2sde!4v1588792949558!5m2!1sde!2sde\"}', '2026-09-20 15:13:17.626'),
('performance', '{\"introQuote\":\"Als SkyPerformance Trainer bieten wir ein umfangreiches Fortbildungsangebot unter der Leitung speziell ausgebildeter Fluglehrer.\",\"badges\":[{\"label\":\"Streckenflugtraining\"},{\"label\":\"Soaringtraining\"},{\"label\":\"Sicherheitstraining\"},{\"label\":\"Rettungsgerätetraining\"},{\"label\":\"Thermik- und Flugtechniktraining\"},{\"label\":\"Groundhandlingtraining\"}],\"categories\":[{\"heading\":\"Sicherheitstraining - Gardasee\",\"subheading\":\"Sicherheitstraining am Gardasee...\",\"description\":\"Fünf Tage für deine Sicherheit, für die Verbesserung von richtigen Reaktionen und deinem fliegerischem Können. Am Südrand der italienischen Alpen liegt der wunderschöne Gardasee, den wir als Ausgangspunkt unseres Sicherheitstrainings genießen dürfen.\",\"image\":\"/images/performance/sicherheitstraining.jpg\",\"link\":\"/performance/sicherheitstraining\"},{\"heading\":\"Rettungsgerätetraining\",\"subheading\":\"Ein Muss für jeden Gleitschirmpiloten...\",\"description\":\"Gleitschirmfliegen ist eigentlich eine sehr sichere Sache aber dennoch kann es vorkommen, dass ihr in eine Situation geratet, die für euch als Pilot unbeherrschbar ist. Ein Muss für jeden Gleitschirm- und Drachenpiloten ist daher ein Rettungsgerätewurftraining mit der eigenen Ausrüstung.\",\"image\":\"/images/performance/rettungsgeraetetraining.jpg\",\"link\":\"/performance/rettungsgeraetetraining\"},{\"heading\":\"Refresherkurs\",\"subheading\":\"Sicher in allen Situationen...\",\"description\":\"Der Refresher-Kurs richtet sich an alle Piloten, die bereits ihre Ausbildung abgeschlossen haben. Wer unseren schönen Sport einmal gelernt hat und aus welchen Gründen auch immer länger nicht mehr geflogen ist.\",\"image\":\"/images/performance/refresher.jpg\",\"link\":\"/performance/refresher\"},{\"heading\":\"Groundhandling Kurs\",\"subheading\":\"Auf Tuchfühlung mit dem Gleitschirm...\",\"description\":\"Den Gleitschirm kennen lernen und als riesigen Lenkdrachen benutzen, Windsprünge meistern, den Hang kreuzen oder mit geöffnetem Segel bergauf laufen – das sind die Lernziele im diesem Seminar. Groundhandling ist das A & O für jeden Piloten, um den eigenen Schirm sicher zu steuern.\",\"image\":\"/images/performance/groundhandling.jpg\",\"link\":\"/performance/groundhandling\"}]}', '2026-09-20 15:12:30.592'),
('reisen', '{\"introQuote\":\"Die Hotspots der Fliegerszene erkunden mit Flugbetreuung.\",\"introHtml\":\"Unsere <a href=\\\"/reisen\\\">Reisen</a> führen uns in die bekannten Fluggebiet-Hotspots. So zählt <a href=\\\"/reisen/bassano-tour\\\">Bassano</a> – das Mekka der Gleitschirmszene – jährlich fest zum Programm. Aber auch entlegene Ziele wollen wir euch nicht vorenthalten und bieten euch Reisen nach <a href=\\\"/reisen/suedafrika-tour\\\">Südafrika</a> und weiteren besonderen Zielen weltweit an. Im Rahmen unserer <a href=\\\"/reisen\\\">Reisen</a> könnt ihr unter Fluglehrerbetreuung sehr viel Erfahrung sammeln, eure Flugtechnik verbessern und zahlreiche großartige Flugstunden genießen.\",\"calendarButtonLink\":\"/buchungskalender\",\"tours\":[{\"heading\":\"Brasilien-Tour\",\"description\":\"Fliegen in Rio de Janeiro – Uma cidade maravilhosa (eine wunderbare Stadt). Bei unserer Rundreise in Brasilien wollen wir neben den Startplätzen in und um Rio auch einige Startplätze im Landesinneren kennen lernen, wir machen außerdem an den bekannten PWC-Geländen Halt. Die Landschaften sind atemberaubend.\",\"image\":\"/images/reisen/brasilien.jpg\",\"link\":\"/reisen/brasilien-tour\"},{\"heading\":\"Kolumbien-Tour\",\"description\":\"Wir fliegen über den grünen Landschaften des Valle del Cauca. Dabei genießen wir die großartige Gastfreundschaft der Kolumbianer und befliegen über mehrere Stationen die besten Fluggebiete von Cali Richtung Medellin. Die sanfte Thermik und das breite Tal mit zahllosen Landemöglichkeiten laden zu gemeinsamen Thermik- und Streckenflügen ein.\",\"image\":\"/images/reisen/kolumbien.jpg\",\"link\":\"/reisen/kolumbien-tour\"},{\"heading\":\"Südafrika-Tour\",\"description\":\"Auf der Südhalbkugel, im Land der unerschöpflichen fliegerischen Möglichkeiten, können wir beste thermische Flugbedingungen unbegrenzt gemeinsam genießen und uns zudem an hochsommerlichen Temperaturen erfreuen. Einerseits erwarten uns phantastische Flüge in den attraktivsten Soaring-, Thermik- und Streckenfluggebieten in Wilderness, Hermanus, Porterville und Kapstadt.\",\"image\":\"/images/reisen/suedafrika.jpg\",\"link\":\"/reisen/suedafrika-tour\"},{\"heading\":\"Bassano-Tour\",\"description\":\"Bassano ist das unbestrittene Mekka der Gleitschirm- und Drachenszene in den Südalpen. Besonders im Winter und zeitigen Frühjahr trifft sich hier die Szene. Die Thermik ist ganzjährig interessant und kann schon früh im Jahr für Streckenflüge in Bella Italia genutzt werden. Von wunderschönen, stundenlangen Thermikflügen am Monte Grappa mit herrlichem Blick auf die Poebene bis zu schönen Streckenflügen ist in Bassano alles möglich.\",\"image\":\"/images/reisen/bassano.jpg\",\"link\":\"/reisen/bassano-tour\"},{\"heading\":\"Slowenien-Tour\",\"description\":\"Thermik und Streckenfliegen in Slowenien in den julischen Alpen heißt fliegen entlang der türkisblauen Soča in der Nähe von Kobarid und Tolmin.\",\"image\":\"/images/reisen/slowenien.jpg\",\"link\":\"/reisen/slowenien-tour\"},{\"heading\":\"Griechenland-Tour\",\"description\":\"Die Flugsafari ist eine tolle Kombination von Thermik- und Streckenfliegen im Pindosgebirge sowie dem Küstensoaren auf der Insel Lefkada an der Westküste Griechenlands..\",\"image\":\"/images/reisen/griechenland.jpg\",\"link\":\"/reisen/griechenland-tour\"},{\"heading\":\"Bergamo-Tour\",\"description\":\"Wer in Italien einmal abseits der ausgetretenen Pfade fliegen möchte, ist goldrichtig in der Region rund um Bergamo, den Ausläufern der Südalpen kurz vor Mailand.\",\"image\":\"/images/reisen/bergamo.jpg\",\"link\":\"/reisen/bergamo-tour\"},{\"heading\":\"Savoyer Alpentour\",\"description\":\"Eine Woche durch die Savoyer Alpen touren. Die Savoyer Alpen befinden sich grob zwischen Genf, Chamonix und Grenoble. Unser Standort ist der Campingplatz La ferme de la Serraz neben dem Lac d\' Annecy in Doussard. Um den See liegen alleine schon 3 Fluggelände, die von der Hauptwindrichtung recht unabhängig und fast täglich fliegbar sind.\",\"image\":\"/images/reisen/savoye.jpg\",\"link\":\"/reisen/savoye-tour\"},{\"heading\":\"Vogesen-Tour\",\"description\":\"Die Vogesen schließen sich nahtlos an das Pfälzer Bergland an und bilden ganz im Süden mit den Fluggebieten le Treh, le Drumont, Gustiberg und Ballon d\'Alsace eine phantastische Flug-Arena. Sie bieten dem Einsteiger einfache Startplätze mit großzügigen Landeplätzen im Gleitwinkelbereich, dem Fortgeschrittenen die Möglichkeit für erste Streckenflüge.\",\"image\":\"/images/reisen/vogesen.jpg\",\"link\":\"/reisen/vogesen-tour\"},{\"heading\":\"Pfalz-Tour\",\"description\":\"Rund um das kleine Städtchen Annweiler in der Südpfalz liegen 7 schöne Startplätze, die allemal einen Besuch wert sind. Die Buckel der Südpfälzer haben einen Höhenunterschied von bis zu 320 m. Es werden von dort regelmäßig schöne Streckenflüge in den DHV-XC eingereicht.\",\"image\":\"/images/reisen/pfalz.jpg\",\"link\":\"/reisen/pfalz-tour\"}]}', '2026-09-20 15:13:15.353'),
('service', '{\"items\":[{\"id\":\"2-jahres-check\",\"title\":\"2-JAHRES-CHECK\",\"description\":\"Wartungsarbeiten und Reparaturen in unserer Service-Werkstätte\",\"image\":\"/images/service/check.jpg\",\"link\":\"/service/2-jahres-check\"},{\"id\":\"rettungspacken\",\"title\":\"RETTUNGSGERÄTE-PACKSERVICE\",\"description\":\"Rettung professionell gepackt! Wir packen sie, als wäre es unsere eigene.\",\"image\":\"/images/service/rettungspackservice.png\",\"link\":\"/service/rettungspacken\"},{\"id\":\"trimmtuning\",\"title\":\"TRIMMTUNING\",\"description\":\"\\\"Trimmtuning\\\" – für bessere und sicherere Schirme! Mit professioneller Leinenvermessung und optimaler Einstellung der Leinenlängen mehr erreichen: Idealerweise kann so in der Luft mehr Leistung rausgeholt werden, ohne dass euer Schirm dadurch an Sicherheit verliert oder anspruchsvoller wird.\",\"image\":\"/images/service/trimmtuning.jpg\",\"link\":\"/service/trimmtuning\"},{\"id\":\"reparatur\",\"title\":\"REPARATUR-SERVICE\",\"description\":\"Defekte an der Ausrüstung? Wir bieten euch einen Reparatur Service für eure Ausrüstung an.\",\"image\":\"/images/service/reparatur.jpg\",\"link\":\"/service/reparatur\"}]}', '2026-09-21 06:52:56.889');
